#!name=小象超市
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = portal-portm.meituan.com, mall.meituan.com

[Rewrite]
request if ${url} ~= /^https?:\/\/portal-portm\.meituan\.com\/horn_ios\/mergeRequest/i then reject_dict(200)
request if ${url} ~= /^https?:\/\/mall\.meituan\.com\/api\/c\/homepage\/splash/i then reject_dict(200)
response if ${url} ~= /^https?:\/\/mall\.meituan\.com\/api\/c\/homepage\/bubble\/operate\/info/i then response.body.mock("json", "{\"code\": 0}")
